CREATE TABLE identities (id TEXT PRIMARY KEY, token_hash TEXT UNIQUE NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE tables (table_id TEXT PRIMARY KEY, schema_version INTEGER NOT NULL DEFAULT 1, revision INTEGER NOT NULL, round_id TEXT NOT NULL, phase TEXT NOT NULL CHECK(phase IN ('open','revealed')), suit TEXT NOT NULL, completion_emitted INTEGER NOT NULL, revealed_snapshot_json TEXT, updated_at INTEGER NOT NULL);
CREATE TABLE memberships (table_id TEXT NOT NULL REFERENCES tables(table_id) ON DELETE CASCADE, identity_id TEXT NOT NULL REFERENCES identities(id) ON DELETE CASCADE, display_name TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('voter','observer')), seat_index INTEGER NOT NULL, last_seen_at INTEGER NOT NULL, last_sequence INTEGER NOT NULL, PRIMARY KEY(table_id,identity_id));
CREATE TABLE votes (table_id TEXT NOT NULL, round_id TEXT NOT NULL, identity_id TEXT NOT NULL, value_json TEXT NOT NULL CHECK(value_json IN ('0','1','2','3','5','8','13','21','34','"?"')), updated_at INTEGER NOT NULL, PRIMARY KEY(table_id,round_id,identity_id), FOREIGN KEY(table_id,identity_id) REFERENCES memberships(table_id,identity_id) ON DELETE CASCADE);
CREATE TABLE command_receipts (table_id TEXT NOT NULL REFERENCES tables(table_id) ON DELETE CASCADE, identity_id TEXT NOT NULL REFERENCES identities(id) ON DELETE CASCADE, command_id TEXT NOT NULL, round_id TEXT NOT NULL, sequence INTEGER NOT NULL, payload_hash TEXT NOT NULL, result_json TEXT NOT NULL, PRIMARY KEY(table_id,identity_id,command_id));
CREATE INDEX receipts_round ON command_receipts(table_id,round_id);
